  async asyncData({
    $content,
    $axios,
    params
  }) {
    const details = await $content(`price-auto/${params.slug}`).fetch();
    const lang = params.slug;
    return {
      details,
      lang,
      $axios
    };
  },

  head() {
    if (this.details) {
      return {
        title: this.details.pageTitle,
        meta: [{
          hid: 'description',
          name: 'description',
          content: this.details.pageDescription
        }]
      };
    }
  },

  data() {
    return {
      totalPrice: '',
      notForPrinting: true,
      isDefault: true,
      priceFields: {
        course: 'esl',
        week: '1',
        visa: 'student_visa',
        accommodation: 'one',
        transport: 'yes'
      },
      resultFields: {
        processing_fee: {
          show: true,
          value: '$150'
        },
        tuition: {
          show: true,
          value: ''
        },
        sevis: {
          show: true,
          value: '$350'
        },
        i20: {
          show: true,
          value: '$120'
        },
        housing_placement: {
          show: true,
          value: ''
        },
        housing_rent: {
          show: true,
          value: ''
        },
        security_deposit: {
          show: true,
          value: '$200'
        },
        maintain_fee: {
          show: true,
          value: ''
        },
        transport: {
          show: true,
          value: ''
        }
      }
    };
  },

  methods: {
    async submitFormEmail(e) {
      e.preventDefault();
      const dataFields = Object.assign({}, this.$refs.sendToEmailModal.getFormData());
      dataFields.language = this.lang;
      dataFields.message = dataFields.message == null ? '' : dataFields.message;
      dataFields.phone_call = !dataFields.phone_call ? false : true;
      await this.$axios.post('/api/price-send-email', dataFields).then(function (response) {
        window.location.href = '/' + this.lang + '/contact/thanks';
      }.bind(this));
    },

    getCourseDescription: function () {
      const course = this.details.defaultText.lists[0].selection.filter(course => course.key == this.priceFields.course);
      return course ? course[0].value : '';
    },
    toggleCompute: function () {
      this.isDefault = !this.isDefault;
    },

    selectChange(forminfo) {
      if (forminfo == 'accommodation') {
        const isReadOnly = this.priceFields[forminfo] != "no";
        this.$refs.ref_transport[0].disabled = isReadOnly;
        if (isReadOnly) this.priceFields['transport'] = 'yes';
      }
    },

    computePrice: function (e) {
      const {
        course,
        week,
        visa,
        accommodation,
        transport
      } = this.priceFields;
      let price = 279;

      if (!course || !week || week < 1 || week > 48) {
        return false;
      }

      if (week >= 1 && week <= 4) {
        price = 293;
      } else if (week >= 5 && week <= 12) {
        price = 239;
      } else if (week == 13) {
        price = 228;
      } else if (week >= 14 && week <= 24) {
        price = 217;
      } else if (week >= 25 && week <= 36) {
        price = 209;
      } else if (week >= 37 && week <= 48) {
        price = 201;
      }

      var cal_week_total = price * week;
      var total_price = cal_week_total + 150;

      switch (visa) {
        // Please list down the other languages
        case 'student_visa':
          total_price += 350 + 100;
          break;

        default:
          this.resultFields.sevis.show = false;
          this.resultFields.i20.show = false;
      }

      if (transport == 'yes') {
        this.resultFields.transport.value = '$150';
        total_price += 150;
      } else {
        this.resultFields.transport.show = false;
      }

      if (accommodation != "no") {
        var maintenance = 0;
        var placement = 0;
        var price_per_week = 0;
        var accommodation_name = '';
        var text = '';

        switch (accommodation) {
          case "home_one":
            accommodation_name = "Homestay(Private)";
            text = "ホームステイ（1人部屋）";
            placement = 270;

            if (week < 4) {
              price_per_week = 436;
            } else {
              price_per_week = 395;
            }

            break;

          case "home_two":
            accommodation_name = "Homestay(Shared)";
            text = "ホームステイ（シェアルーム）";
            placement = 270;

            if (week < 4) {
              price_per_week = 384;
            } else {
              price_per_week = 363;
            }

            break;

          case "one":
            accommodation_name = "Dormitory (Private Room)";
            text = "寮（1人部屋）";
            placement = 270;

            if (week < 4) {
              maintenance = 25 * week;
              price_per_week = 517;
            } else {
              maintenance = 100;
              price_per_week = 500;
            }

            break;

          case "two":
            accommodation_name = "Dormitory (Shared-2 Room)";
            text = "寮（2人部屋）";
            placement = 270;

            if (week < 4) {
              maintenance = 25 * week;
              price_per_week = 380;
            } else {
              maintenance = 100;
              price_per_week = 350;
            }

            break;

          case "four":
            accommodation_name = "Dormitory (Shared-4 Room)";
            text = "寮（4人部屋）";
            placement = 270;

            if (week < 4) {
              maintenance = 25 * week;
              price_per_week = 270;
            } else {
              maintenance = 100;
              price_per_week = 250;
            }

            break;

          default:
            text = "手配の必要なし";
            price_per_week = 0;
        }

        if (accommodation != 'no' && transport != 'yes') {
          placement = placement + 30;
        }

        var total_stay = price_per_week * week; // + maintenance;

        total_price += total_stay + placement + maintenance + 200; //200 Security Desposit

        this.totalPrice = total_price;
        this.resultFields.housing_rent.value = "$" + total_stay;
        this.resultFields.housing_placement.value = "$" + placement; // $('#accommodation_type').text(accommodation_name);

        if (accommodation == "one" || accommodation == "two" || accommodation == "four") {
          this.resultFields.maintain_fee = {
            value: "$" + maintenance,
            show: true
          };
        } else {
          this.resultFields.maintain_fee.show = false;
        }
      } else {
        this.resultFields.housing_placement.show = false;
        this.resultFields.housing_rent.show = false;
        this.resultFields.maintain_fee.show = false;
        this.resultFields.security_deposit.show = false;
      }

      this.resultFields.tuition.value = "$" + cal_week_total;
      var week_text = "weeks";

      if (week == 1) {
        week_text = "week";
      } // $("#course_week").text( week + week_text);
      // $("#course_week2").text( week + week_text);


      this.totalPrice = total_price;
      this.toggleCompute();
    },

    estimateButtons(btn) {
      const vm = this;

      switch (btn) {
        case 'print':
          const self = this;
          this.notForPrinting = false;
          setTimeout(function () {
            const divToPrint = document.getElementById("printable");
            const newWin = window.open("");
            newWin.document.write(divToPrint.outerHTML);
            newWin.print();
            newWin.close();
            self.notForPrinting = true;
          }, 100);
          return;
      }
    }

  },

  mounted() {
    this.$refs.ref_transport[0].disabled = true;
  }

